import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.D31cdF9L.js";import"./chunks/assets.DM0yF35s.js";var i=JSON.parse(`{"title":"Quick Start","description":"","frontmatter":{},"headers":[],"relativePath":"guide/quick-start.md","filePath":"guide/quick-start.md"}`),a={name:`guide/quick-start.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to “Quick Start”">​</a></h1><p>Your first export takes under a minute. Here&#39;s the whole workflow.</p><h2 id="step-1-open-a-blueprint" tabindex="-1">Step 1: Open a Blueprint <a class="header-anchor" href="#step-1-open-a-blueprint" aria-label="Permalink to “Step 1: Open a Blueprint”">​</a></h2><p>Open any Blueprint in your project (a Character, GameMode, Actor, or even a Widget Blueprint).</p><h2 id="step-2-click-graphscribe-and-pick-a-format" tabindex="-1">Step 2: Click GraphScribe and pick a format <a class="header-anchor" href="#step-2-click-graphscribe-and-pick-a-format" aria-label="Permalink to “Step 2: Click GraphScribe and pick a format”">​</a></h2><p>In the Blueprint editor, find the <strong>GraphScribe</strong> button in the toolbar and click it. An export dialog opens (titled <code>GraphScribe — &lt;Asset Name&gt;</code>) with a live preview of the export:</p><ul><li><strong>Format:</strong> <a href="/GraphScribe-Documentation/guide/markdown-output.html">Markdown</a>, <a href="/GraphScribe-Documentation/guide/graphify-output.html">Graphify</a>, <a href="/GraphScribe-Documentation/guide/mermaid-output.html">Mermaid</a>, or <a href="/GraphScribe-Documentation/guide/json-output.html">JSON</a>.</li><li><strong>Preview:</strong> a read-only view of the full export in the selected format, updated live.</li><li><strong>Copy:</strong> copies the export text to the clipboard.</li><li><strong>Save As...:</strong> writes the export to a file.</li><li><strong>Close:</strong> closes the dialog.</li></ul><p><img src="/GraphScribe-Documentation/img/toolbar-button.png" alt="GraphScribe toolbar button in the Blueprint editor" width="1803" height="863"></p><p><img src="/GraphScribe-Documentation/img/export-dialog.png" alt="GraphScribe export dialog with the format combo and live preview" width="1800" height="908"></p><h2 id="step-3-save-your-export" tabindex="-1">Step 3: Save your export <a class="header-anchor" href="#step-3-save-your-export" aria-label="Permalink to “Step 3: Save your export”">​</a></h2><p>Click <strong>Save As</strong>. A system save dialog opens, pre-filled with your configured <a href="/GraphScribe-Documentation/guide/settings.html">save directory</a> and the asset name with the right extension:</p><ul><li><code>.md</code> for Markdown</li><li><code>.graphify.json</code> for Graphify</li><li><code>.mmd</code> for Mermaid</li><li><code>.json</code> for JSON</li></ul><p>Pick a location and confirm. If <a href="/GraphScribe-Documentation/guide/settings.html">Open Folder After Save</a> is enabled, the editor opens the file&#39;s folder for you.</p><p><img src="/GraphScribe-Documentation/img/saved-files-explorer.png" alt="File explorer showing the freshly saved export file" width="1906" height="888"></p><p>Open the Markdown file and read it. Your Blueprint&#39;s variables, functions, and graphs are all plain text now, so anyone can read them.</p><h2 id="what-to-try-next" tabindex="-1">What to try next <a class="header-anchor" href="#what-to-try-next" aria-label="Permalink to “What to try next”">​</a></h2><ul><li><strong>Export a whole folder:</strong> Right-click a Content Browser folder → <strong>Export Blueprints with GraphScribe...</strong> exports every supported asset under it. See <a href="/GraphScribe-Documentation/guide/exporting.html">Ways to Export</a>.</li><li><strong>Export selected nodes only:</strong> Select some nodes in a graph, right-click, and pick <strong>Export Selection with GraphScribe...</strong>.</li><li><strong>Read your first export:</strong> <a href="/GraphScribe-Documentation/guide/markdown-output.html">Markdown Output</a> explains every section you&#39;ll see.</li><li><strong>See the AI-ready version:</strong> <a href="/GraphScribe-Documentation/guide/graphify-output.html">Graphify: AI-Ready Graphs</a> shows why the Graphify format is different from the others.</li></ul>`,17)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};